import 'package:flutter/material.dart';class NeonText extends StatelessWidget{final String text;final double fontSize;final Color color;const NeonText(this.text,{super.key,this.fontSize=18,this.color=Colors.white});@override Widget build(BuildContext c)=>Text(text,textAlign:TextAlign.center,style:TextStyle(color:color,fontSize:fontSize,fontWeight:FontWeight.w700,shadows:[Shadow(color:color.withOpacity(.7),blurRadius:8),Shadow(color:color.withOpacity(.3),blurRadius:24)]));}